const STALE_HOURS = 18;
const DISK_WARN = 80;
const job = $('Run Housekeeping').first().json;
const r = job.result ?? {};
const now = Date.now();
const running = $input.all().map((i) => i.json).filter((x) => x && x.run_id && x.status === 'running');
const stale = running.filter((x) => now - Date.parse(x.started) > STALE_HOURS * 3600e3)
  .map((x) => ({ run_id: x.run_id, engagement: x.engagement, started: x.started }));

const issues = [];
if ((r.disk_pct ?? 0) >= DISK_WARN) issues.push(`Disk at ${r.disk_pct}% on /opt/loot`);
if (stale.length) issues.push(`${stale.length} run(s) stuck in 'running' for over ${STALE_HOURS}h: ${stale.map((s) => `${s.engagement}/${s.run_id}`).join(', ')}`);
if (r.stale_locks?.length) issues.push(`Stale engagement locks: ${r.stale_locks.join(', ')}`);
if (r.missing_images?.length) issues.push(`Missing Docker images: ${r.missing_images.join(', ')}`);
if (r.templates_rc && r.templates_rc !== 0) issues.push(`nuclei template update failed (rc=${r.templates_rc})`);
if (job.timed_out) issues.push('Housekeeping job timed out');

const weekly = new Date().getUTCDay() === 1;
const freed = (r.loot_mb_before ?? 0) - (r.loot_mb_after ?? 0);
const fields = [
  { name: 'Disk', value: `${r.disk_pct ?? '?'}% used`, inline: true },
  { name: '/opt/loot', value: `${r.loot_mb_after ?? '?'} MB${freed > 0 ? ` (freed ${freed} MB)` : ''}`, inline: true },
  { name: 'Templates', value: `${r.templates_before || '?'} → ${r.templates_after || '?'}`, inline: true },
  { name: 'Runs compressed', value: String(r.compressed?.length ?? 0), inline: true }
];
if (issues.length) fields.unshift({ name: 'Needs attention', value: issues.map((i) => `• ${i}`).join('\n').slice(0, 1024) });

return [{ json: {
  stale,
  post: issues.length > 0 || weekly,
  embed: {
    title: issues.length ? '⚠️ ASM housekeeping: attention needed' : '🧹 ASM weekly housekeeping',
    color: issues.length ? 0xF39C12 : 0x2ECC71,
    fields,
    footer: { text: 'ASM · Housekeeping' },
    timestamp: new Date().toISOString()
  }
} }];
